import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        DataInputStream in = new DataInputStream(new BufferedInputStream(System.in, 1 << 16));
        int n = (int) readLong(in);
        long x = readLong(in);
        long[] c = new long[n];
        for (int i = 0; i < n; i++) c[i] = readLong(in);
        final long MOD = 1_000_000_007L;
        long[] pw = new long[n];
        for (int i = 0; i < n; i++) pw[i] = i == 0 ? 1 : pw[i - 1] * 2 % MOD;
        long rem = x, ans = 0;
        // Greedy from the highest index: 2^i beats all lower profits combined.
        for (int i = n - 1; i >= 0; i--) {
            if (c[i] <= rem) {
                rem -= c[i];
                ans = (ans + pw[i]) % MOD;
            }
        }
        System.out.println(ans);
    }

    static long readLong(DataInputStream in) throws IOException {
        int b = in.read();
        while (b != '-' && (b < '0' || b > '9')) b = in.read();
        boolean neg = false;
        if (b == '-') { neg = true; b = in.read(); }
        long r = 0;
        while (b >= '0' && b <= '9') { r = r * 10 + (b - '0'); b = in.read(); }
        return neg ? -r : r;
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<16)
	var n int
	var x int64
	fmt.Fscan(in, &n, &x)
	c := make([]int64, n)
	for i := range c {
		c[i] = readInt(in)
	}
	const MOD = 1_000_000_007
	pw := make([]int64, n)
	for i := 0; i < n; i++ {
		if i == 0 {
			pw[i] = 1
		} else {
			pw[i] = pw[i-1] * 2 % MOD
		}
	}
	rem, ans := x, int64(0)
	// Greedy from the highest index: 2^i beats all lower profits combined.
	for i := n - 1; i >= 0; i-- {
		if c[i] <= rem {
			rem -= c[i]
			ans = (ans + pw[i]) % MOD
		}
	}
	fmt.Println(ans)
}

func readInt(in *bufio.Reader) int64 {
	b, _ := in.ReadByte()
	for b != '-' && (b < '0' || b > '9') {
		b, _ = in.ReadByte()
	}
	neg := false
	if b == '-' {
		neg = true
		b, _ = in.ReadByte()
	}
	var r int64
	for b >= '0' && b <= '9' {
		r = r*10 + int64(b-'0')
		b, _ = in.ReadByte()
	}
	if neg {
		return -r
	}
	return r
}
